using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Threading;
namespace PZ3D {
 // Downloads and specialized installers are injected at the native boundary. All
 // dependency identity, ordering and default-list changes use freshly read files.
 sealed class JavaComponentWorkflow {
  internal sealed class Missing {public string modId,name,reason;}
  internal sealed class Result {public string status="failed",message="Java 模组操作未完成。";public JavaComponents.Row[] rows=new JavaComponents.Row[0];public string[] enabled=new string[0],downloaded=new string[0];public Missing[] unresolved=new Missing[0];public bool cancelled,changed,recoveryPending;}
  readonly Engine engine;readonly JavaComponents manager;readonly Action<string,Action<int,string>,CancellationToken> download;readonly Func<string,Action<int,string>,CancellationToken,string> resolve;readonly Func<string,string> installKnown;readonly Action<int,string> progress;SaveProfiles.PreflightCatalog catalog;JavaComponents.Inventory cachedInventory;DateTime nextCatalogReport;int catalogFiles;
  internal JavaComponentWorkflow(Engine engine,JavaComponents manager,Action<string,Action<int,string>,CancellationToken> download,Func<string,Action<int,string>,CancellationToken,string> resolve,Func<string,string> installKnown,Action<int,string> progress){this.engine=engine;this.manager=manager;this.download=download;this.resolve=resolve;this.installKnown=installKnown;this.progress=progress;}
  void Report(string text){if(progress!=null)progress(-1,text);}
  static bool Workshop(string id){ulong value;return ulong.TryParse(id,out value)&&value>0&&value.ToString()==id;}
  static string Canonical(string id){return (id??"").TrimStart('\\');}
  static string Known(string id){switch(Canonical(id)){case "ZombieBuddy":return "buddy";case "Viewpoint":return "viewpoint";case "PZVoxelStudioViewpoint":return "models";case "ShootToThrillMultiplayer":return "shoot";case "LaoYuTranslationJava":return "chinese";}var addon=ViewpointAddons.All.FirstOrDefault(a=>a.Id==Canonical(id));return addon==null?"":addon.Key;}
  void Fetch(string id,Result result,CancellationToken token){token.ThrowIfCancellationRequested();if(!Workshop(id)||download==null)throw new IOException("无法下载工坊项目："+id);Report("正在下载 Java 模组与依赖 · 已下载 "+result.downloaded.Length+" 项 · "+id);download(id,progress,token);catalog=null;cachedInventory=null;result.downloaded=result.downloaded.Concat(new[]{id}).Distinct().ToArray();result.changed=true;token.ThrowIfCancellationRequested();}
  internal Result Install(string id,bool confirmed,CancellationToken token){return Execute(confirmed,token,result=>{if(!Workshop(id))throw new IOException("请输入有效的数字工坊项目 ID。");Fetch(id,result,token);Report("正在识别下载的 Java 模组 · "+id);var inventory=manager.ReadInventory(token,ulong.Parse(id));result.rows=inventory.rows;if(inventory.incomplete)throw new IOException("下载的模组来源未完整核实："+string.Join("；",inventory.warnings));if(result.rows.Length==0){result.status="unsupported";result.message="工坊项目 "+id+" 已下载，但未发现标准 Java 加载声明；Lua 模组或独立安装脚本不由此流程启用。";return;}if(result.rows.Length>1){result.status="selectionRequired";result.message="此工坊包有多个 Java 子模组，请选择要启用的一项。";return;}EnableSelected(result.rows[0].token,result,token);});}
  internal Result Enable(string selected,bool confirmed,CancellationToken token){return Execute(confirmed,token,result=>EnableSelected(selected,result,token));}
  internal Result Reconcile(bool confirmed,CancellationToken token){if(!confirmed)return new Result{status="cancelled",cancelled=true,message="已取消 Java 状态核对。"};var value=manager.Reconcile(token);return new Result{status=value.status,message=value.message,changed=value.changed,cancelled=value.status=="cancelled",recoveryPending=value.recoveryPending,unresolved=value.status=="unresolved"?value.message.Split('\n').Select(message=>new Missing{modId=message.Split('：')[0],name=message.Split('：')[0],reason=message}).ToArray():new Missing[0]};}
  internal static JavaComponents.Result ReconcileBeforeLaunch(Engine selected,CancellationToken token,Action<int,string> progress){if(selected.FrozenEnvironment!=null)return new JavaComponents.Result{status="unchanged",message="快照内的 Java 组件保持固定。"};using(var service=new JavaComponents(selected,progress))return service.Reconcile(token);}
  Result Execute(bool confirmed,CancellationToken token,Action<Result> work){catalog=null;cachedInventory=null;var result=new Result();byte[] initial=null;bool baseline=false;try{if(!confirmed)throw new OperationCanceledException();token.ThrowIfCancellationRequested();if(engine.FrozenEnvironment!=null)throw new IOException("快照内的 Java 组件保持固定；请在当前环境中管理组件后新建快照。");initial=SaveProfiles.DefaultBytes(engine);baseline=true;work(result);}catch(Exception ex){result.cancelled=ex is OperationCanceledException;result.status=result.cancelled?"cancelled":result.recoveryPending?"recoveryRequired":result.unresolved.Length>0?"unresolved":"failed";result.message=result.cancelled?"已取消；已下载文件与已启用的依赖保留，可继续操作。":ex.Message;}
   if(baseline)try{var now=SaveProfiles.DefaultMods(SaveProfiles.DefaultBytes(engine)).Select(Canonical).ToArray();result.enabled=result.enabled.Concat(now.Except(SaveProfiles.DefaultMods(initial).Select(Canonical))).Where(now.Contains).Distinct().ToArray();result.changed|=!(initial??new byte[0]).SequenceEqual(SaveProfiles.DefaultBytes(engine)??new byte[0]);}catch(Exception ex){result.status="failed";result.message+=" 无法读取最终清单："+ex.Message;}return result;}
  void MissingItem(Result result,string id,string reason){result.unresolved=result.unresolved.Concat(new[]{new Missing{modId=id,name=id,reason=reason}}).ToArray();throw new IOException(id+"："+reason);}
  List<SaveProfiles.Entry> Catalog(string id,CancellationToken token){
   if(catalog==null){catalogFiles=0;nextCatalogReport=DateTime.MinValue;var budget=new LaunchReadBudget(67108864,100000);budget.Checkpoint=(file,size)=>{token.ThrowIfCancellationRequested();if(file!=null){catalogFiles++;if(DateTime.UtcNow>=nextCatalogReport){Report("正在核对依赖 · 已读取 "+catalogFiles+" 个文件 · "+id);nextCatalogReport=DateTime.UtcNow.AddMilliseconds(200);}}};var warnings=new List<string>();catalog=SaveProfiles.SnapshotEntries(engine,new[]{id},warnings,budget);token.ThrowIfCancellationRequested();Report("依赖目录读取完成 · 已读取 "+catalogFiles+" 个文件");if(budget.Incomplete)throw new IOException("依赖来源未完整读取："+id);
   }else catalog.Select(new[]{id});token.ThrowIfCancellationRequested();return catalog.Entries;
  }
  JavaComponents.Inventory Inventory(CancellationToken token){token.ThrowIfCancellationRequested();return cachedInventory??(cachedInventory=manager.ReadInventory(token));}

  void EnableSelected(string selected,Result result,CancellationToken token){
   Report("正在识别 Java 模组与依赖 · 已处理 0 项");var inventory=Inventory(token);var matches=inventory.rows.Where(row=>row.token==selected).ToArray();if(matches.Length!=1)throw new IOException("所选 Java 模组已变化，请刷新列表。");string target=matches[0].modId;result.rows=string.IsNullOrEmpty(matches[0].workshopId)?matches:inventory.rows.Where(row=>row.workshopId==matches[0].workshopId).ToArray();
   var state=new Dictionary<string,int>(StringComparer.Ordinal);var ordered=new List<string>();var attempted=new HashSet<string>(StringComparer.Ordinal);
   Action<string> visit=null;visit=id=>{token.ThrowIfCancellationRequested();id=Canonical(id);int prior;if(state.TryGetValue(id,out prior)){if(prior==1)MissingItem(result,id,"依赖形成循环，未开始启用。");return;}if(state.Count>=2000)MissingItem(result,id,"依赖数量超过读取限制。");state[id]=1;Report("正在核对依赖 · 已识别 "+state.Count+" 项 · "+id);string key=Known(id);
    var entries=Catalog(id,token).Where(entry=>Canonical(entry.id)==id).ToArray();if(entries.Length>1)MissingItem(result,id,"存在多个本地来源，不能确定启用哪一份。");
    if(entries.Length==0&&key==""){if(resolve==null)MissingItem(result,id,"本地缺失且无法取得明确工坊来源。");string source;try{source=resolve(id,progress,token);}catch(OperationCanceledException){throw;}catch(Exception ex){MissingItem(result,id,ex.Message);return;}if(!Workshop(source))MissingItem(result,id,"未找到唯一且明确声明此模组 ID 的工坊项目。");if(!attempted.Add(source))MissingItem(result,id,"已下载的工坊项目仍没有此模组 ID。");Fetch(source,result,token);entries=Catalog(id,token).Where(entry=>Canonical(entry.id)==id).ToArray();if(entries.Length!=1)MissingItem(result,id,entries.Length==0?"下载后仍未找到作者声明的此模组 ID。":"下载后发现重复来源。");}
    foreach(string dependency in entries.SelectMany(entry=>entry.requires??new string[0]).Select(Canonical).Distinct())visit(dependency);state[id]=2;ordered.Add(id);
   };visit(target);
   // Standard Java mods need the framework even if their author omitted require.
   if(Known(target)==""&&!ordered.Contains("ZombieBuddy")){ordered.Insert(0,"ZombieBuddy");}
   var applied=new List<string>();foreach(string id in ordered){token.ThrowIfCancellationRequested();Report("正在启用 Java 模组与依赖 · 已处理 "+applied.Count+" / "+ordered.Count+" 项 · "+id);string key=Known(id);if(key!=""){
     bool ready=id=="ZombieBuddy"&&CoreComponents.FrameworkReady(engine);if(!ready){if(installKnown==null)MissingItem(result,id,"需要使用组件安装器，但此安装器不可用。");string response;try{response=installKnown(key);}finally{catalog=null;cachedInventory=null;}if((response??"").Contains("[失败]"))MissingItem(result,id,response);if(!SaveProfiles.DefaultMods(SaveProfiles.DefaultBytes(engine)).Select(Canonical).Contains(id)||id=="ZombieBuddy"&&!CoreComponents.FrameworkReady(engine))MissingItem(result,id,"组件安装器尚未完成此项启用，请检查安装结果。");}
    }else{var current=Inventory(token);var java=current.rows.Where(row=>row.modId==id).ToArray();if(java.Length>1)MissingItem(result,id,"Java 模组存在重复来源。");if(java.Length==1){var appliedResult=manager.EnableSelected(java[0].token,token);result.changed|=appliedResult.changed;result.recoveryPending|=appliedResult.recoveryPending;if(appliedResult.status!="completed"&&appliedResult.status!="unchanged"){if(appliedResult.status=="cancelled")throw new OperationCanceledException();MissingItem(result,id,appliedResult.message);}}}
    applied.Add(id);ApplyOrder(applied,token);result.enabled=applied.ToArray();token.ThrowIfCancellationRequested();
   }var selectedTokens=new HashSet<string>(result.rows.Select(row=>row.token));cachedInventory=null;result.rows=Inventory(token).rows.Where(row=>selectedTokens.Contains(row.token)).ToArray();result.status="completed";result.message="已启用所选 Java 模组及依赖，共 "+applied.Count+" 项；下次启动生效。";
  }
  void ApplyOrder(List<string> ids,CancellationToken token){string name="Local\\OrangeLaunch-"+DlssInstaller.Hash(Encoding.UTF8.GetBytes(Path.GetFullPath(engine.User).ToUpperInvariant()));using(var mutex=new Mutex(false,name)){bool held=false;try{try{held=mutex.WaitOne(0);}catch(AbandonedMutexException){held=true;}if(!held)throw new IOException("默认模组清单正在修改，请稍后重试。");token.ThrowIfCancellationRequested();engine.GuardContent();LauncherMaintenance.NoReparse(engine.Mods);byte[] original=SaveProfiles.DefaultBytes(engine);string[] current=SaveProfiles.DefaultMods(original);var ordered=ids.Select(id=>current.FirstOrDefault(value=>Canonical(value)==id)??id).Concat(current.Where(id=>!ids.Contains(Canonical(id)))).ToArray();if(current.Select(Canonical).SequenceEqual(ordered.Select(Canonical)))return;byte[] output=SaveProfiles.ReplaceDefaultMods(original,ordered);Directory.CreateDirectory(Path.GetDirectoryName(engine.Mods));string temporary=engine.Mods+".java-"+Guid.NewGuid().ToString("N");try{using(var file=new FileStream(temporary,FileMode.CreateNew,FileAccess.Write,FileShare.None)){file.Write(output,0,output.Length);file.Flush(true);}engine.GuardContent();if(!(original??new byte[0]).SequenceEqual(SaveProfiles.DefaultBytes(engine)??new byte[0]))throw new IOException("默认模组清单已变化，未覆盖。");if(File.Exists(engine.Mods))File.Replace(temporary,engine.Mods,null);else File.Move(temporary,engine.Mods);}finally{if(File.Exists(temporary))File.Delete(temporary);}}finally{if(held)mutex.ReleaseMutex();}}}
 }
}
